export function parsePort(value: string): number {
  if (!/^[0-9]+$/.test(value)) {
    throw new Error("Port must be a valid integer from 1 to 65535.");
  }
  const port = Number.parseInt(value, 10);
  if (port < 1 || port > 65535) {
    throw new Error("Port must be a valid integer from 1 to 65535.");
  }
  return port;
}

